package com.axsos.Life.models; import jakarta.validation.constraints.*; import org.springframework.format.annotation.DateTimeFormat; import java.time.LocalDate;
public class InBodyForm { @NotNull @PastOrPresent @DateTimeFormat(pattern="yyyy-MM-dd") private LocalDate reportDate; @NotNull @DecimalMin("30") @DecimalMax("350") private Double weight; @DecimalMin("5") @DecimalMax("150") private Double muscleMass; @DecimalMin("1") @DecimalMax("75") private Double bodyFatPercentage; @Min(1) @Max(60) private Integer visceralFatLevel; @DecimalMin("10") @DecimalMax("100") private Double totalBodyWater; @Min(500) @Max(5000) private Integer bmr;
 public LocalDate getReportDate(){return reportDate;} public void setReportDate(LocalDate v){reportDate=v;} public Double getWeight(){return weight;} public void setWeight(Double v){weight=v;} public Double getMuscleMass(){return muscleMass;} public void setMuscleMass(Double v){muscleMass=v;} public Double getBodyFatPercentage(){return bodyFatPercentage;} public void setBodyFatPercentage(Double v){bodyFatPercentage=v;} public Integer getVisceralFatLevel(){return visceralFatLevel;} public void setVisceralFatLevel(Integer v){visceralFatLevel=v;} public Double getTotalBodyWater(){return totalBodyWater;} public void setTotalBodyWater(Double v){totalBodyWater=v;} public Integer getBmr(){return bmr;} public void setBmr(Integer v){bmr=v;}}
